import{_ as t}from"./plugin-vue_export-helper-c27b6911.js";import{r as n,o as p,c as o,a as s,w as c,f as r}from"./app-36705845.js";const l={},i=r(`<h1 id="数组" tabindex="-1"><a class="header-anchor" href="#数组" aria-hidden="true">#</a> 数组</h1><p>数组是一切数据结构的起点，或者说，在计算机世界里，唯一被硬件支持的数据结构就是数组，因为内存的模型就是一个巨大的可以被随机读写的数组，如何合理的划分，组织，就成为了数据结构研究的内容。</p><h2 id="数组的定义" tabindex="-1"><a class="header-anchor" href="#数组的定义" aria-hidden="true">#</a> 数组的定义</h2><p><strong>数组</strong>是一种线性数据结构，它用一组连续的内存空间，来存储一组具有相同类型的数据。元素在数组中的位置被称为<strong>索引</strong>或<strong>数组下标</strong>，一般在C/C++等编程语言中，第一个元素的索引为0，第二个元素的索引为1，以此类推。划分给数组的大小往往是固定的，被称为<strong>数组的容量</strong>，而实际存放的元素个数，被称为<strong>数组的长度</strong>。</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token comment">// 存储在栈上</span>
<span class="token keyword">int</span> arr1<span class="token punctuation">[</span><span class="token number">5</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">,</span> <span class="token number">5</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token comment">// 存储在堆上</span>
<span class="token keyword">int</span><span class="token operator">*</span> arr2 <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token keyword">int</span><span class="token punctuation">[</span><span class="token number">5</span><span class="token punctuation">]</span> <span class="token punctuation">{</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">,</span> <span class="token number">5</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="数组的操作" tabindex="-1"><a class="header-anchor" href="#数组的操作" aria-hidden="true">#</a> 数组的操作</h2><p>访问数组，如果我们知道了数组的起始地址，已经存放的元素大小，那么就可以快速计算出任意元素的地址，从而快速访问任意元素。这种访问方式被称为<strong>随机访问</strong>，因为我们可以随机访问任意元素。计算公式为：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>元素地址 = 基地址 + 下标 × 元素大小
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>由于地址可以直接计算得到，所以随机访问的时间复杂度是 <code>O(1)</code>。但<strong>插入</strong>和<strong>删除</strong>操作则不同：为了保持元素在内存中的连续性，插入需要把插入点之后的元素整体后移，删除则需要把删除点之后的元素整体前移，这两种操作在最坏情况下的时间复杂度都是 <code>O(n)</code>。</p><p>试一试，在下面的可视化组件中体验数组的随机访问、插入与删除操作，注意观察插入和删除时元素的搬移过程。</p>`,10);function u(d,k){const a=n("ArrayVisualizer"),e=n("ClientOnly");return p(),o("div",null,[i,s(e,null,{default:c(()=>[s(a)]),_:1})])}const b=t(l,[["render",u],["__file","数组.html.vue"]]);export{b as default};
